import com.google.gson.JsonParser;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch36Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static CardInstance card(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    public static void main(String[] args){shadow();plasma();storm();shelter();victory();charm();System.out.println("NonPokemonBatch36Test passed: live supplied-type/printed Plasma identity shields, Resistance removal for both players and recoil, Stadium departure, typed continuous cure/immunity, exact named free attacks and conjunctive Ultra Beast legacy-family protection");}
    static void shadow(){for(EnergyType energy:List.of(EnergyType.DARKNESS,EnergyType.GRASS)){
        var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile("xy1_en_126"),EnergyProfile.fixed(energy,2),DynamicPassiveModifierTest.attack(40,false,false));UUID a=DynamicPassiveModifierTest.A,b=DynamicPassiveModifierTest.B;
        for(UUID p:List.of(a,b))m.attachEnergyByEffect(a,p,EffectSourceZone.HAND,card(m,p,"special").instanceId(),p,m.activePokemonView(p).pokemonId());m.playTrainer(a,card(m,a,"stadium").instanceId(),null);m.attack(a,"hit");m.attack(b,"hit");check(m.activePokemonView(a).damage()==(energy==EnergyType.DARKNESS?40:80)&&m.activePokemonView(b).damage()==(energy==EnergyType.DARKNESS?40:80),"Shadow Circle used printed Pokemon type or wrong owner");
        m.discardStadiumByEffect(a);m.attack(a,"hit");check(m.activePokemonView(b).damage()==(energy==EnergyType.DARKNESS?120:160),"Weakness remained removed after Stadium left");
    }}
    static ServerMatch plasmaGame(String energy){String[] ids={"basic","basic","basic","energy",energy,"trainer"};var defs=new ArrayList<CardDefinition>();
        for(String id:Arrays.stream(ids).distinct().toList())defs.add(new CardDefinition(id,id,id.equals("basic")?CardCategory.POKEMON:id.equals("trainer")?CardCategory.TRAINER:CardCategory.ENERGY,id.equals("trainer")?TrainerCategory.STADIUM:TrainerCategory.NONE,"H",Set.of("international"),id.equals("basic"),id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var combat=new CombatCatalog(Map.of("basic",new PokemonProfile(500,1,null,EnergyType.COLORLESS,2,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),List.of(),EnergyType.GRASS)),Map.of("energy",EnergyType.COLORLESS),Map.of("trainer",profile("bw8_en_124")),Map.of(energy,EnergyProfile.fixed(EnergyType.COLORLESS,1)));
        for(int seed=0;seed<100;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,ids[i%ids.length]));decks.add(cs);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,20);m.drawCardsByEffect(A,B,20);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->Arrays.stream(ids).allMatch(id->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(id)))))return m;}throw new AssertionError("Plasma fixture unavailable");
    }
    static void plasma(){for(String id:List.of("bw10_en_091","bw8_en_127","bw9_en_106","other-special")){
        var m=plasmaGame(id);for(UUID p:List.of(A,B))m.attachEnergyByEffect(A,p,EffectSourceZone.HAND,card(m,p,id).instanceId(),p,m.activePokemonView(p).pokemonId());m.playTrainer(A,card(m,A,"trainer").instanceId(),null);m.attack(A,"hit");m.attack(B,"hit");int expected=id.equals("other-special")?200:100;check(m.activePokemonView(A).damage()==expected&&m.activePokemonView(B).damage()==expected,"Plasma Frigate did not inspect physical Energy identity");
        m.moveAttachedEnergyByEffect(A,B,m.activePokemonView(B).pokemonId(),B,m.benchPokemonView(B).getFirst().pokemonId(),List.of(m.activePokemonView(B).attachedEnergyIds().getFirst()));m.attack(A,"hit");check(m.activePokemonView(B).damage()==expected+200,"Plasma shield cached after Energy movement");
    }}
    static void storm(){for(String id:List.of("xy2_en_091","xyalt_en_058"))for(String mode:List.of("native","self_damage","recoil")){
        var attack=AttackSelfDamageCalculationTest.attack(mode,30,EnergyType.GRASS,"");var m=DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),profile(id),EnergyProfile.fixed(EnergyType.GRASS,2),attack,List.of(),30);UUID a=DynamicPassiveModifierTest.A,b=DynamicPassiveModifierTest.B;m.playTrainer(a,card(m,a,"stadium").instanceId(),null);m.attack(a,"hit");check(m.activePokemonView(a).damage()==60&&m.activePokemonView(b).damage()==80&&!m.lastAttack().resistanceApplied(),"Magnetic Storm did not remove attack/recoil Resistance");m.discardStadiumByEffect(b);m.attack(b,"hit");check(m.activePokemonView(a).damage()==110&&m.activePokemonView(b).damage()==110&&m.lastAttack().resistanceApplied(),"Resistance did not return after Stadium left");
    }}
    static void shelter(){for(EnergyType type:List.of(EnergyType.METAL,EnergyType.GRASS)){
        var m=GeneratedRuleBatch8Test.fixture(List.of(),EnergyType.GRASS,type,profile("xy4_en_105"),GeneratedRuleBatch8Test.hit(10,false));for(UUID p:List.of(A,B)){m.applySpecialConditionByEffect(A,p,SpecialCondition.POISONED);m.applySpecialConditionByEffect(A,p,SpecialCondition.BURNED);}m.playTrainer(A,card(m,A,"trainer").instanceId(),null);for(UUID p:List.of(A,B)){check(m.activePokemonView(p).conditions().isEmpty()==(type==EnergyType.METAL),"Steel Shelter failed immediate typed cure");m.applySpecialConditionByEffect(A,p,SpecialCondition.CONFUSED);check(m.activePokemonView(p).conditions().contains(SpecialCondition.CONFUSED)==(type!=EnergyType.METAL),"Steel Shelter failed continuous prevention");}
        if(type==EnergyType.METAL){m.evolve(A,m.activePokemonView(A).pokemonId(),card(m,A,"evolved").instanceId());m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);check(m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED),"Steel Shelter retained immunity after non-Metal evolution");}m.discardStadiumByEffect(A);m.applySpecialConditionByEffect(A,B,SpecialCondition.PARALYZED);check(m.activePokemonView(B).conditions().contains(SpecialCondition.PARALYZED),"Steel Shelter remained after leaving play");
    }}
    static void victory(){var attack=BundledCombatData.attack(JsonParser.parseString("{\"id\":\"expensive\",\"nameZh\":\"Test\",\"energyCost\":{\"FIRE\":2,\"COLORLESS\":1},\"baseDamage\":100,\"damageType\":\"FIRE\",\"effectSupport\":\"SUPPORTED\"}").getAsJsonObject(),EffectRegistry.standard());for(String name:List.of("Victini-EX","Victini","Victini ex"))for(boolean disabled:List.of(false,true)){
        var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("bw8_en_130");c.ownName=name;c.attack=attack;var m=GeneratedRuleBatch28Test.fixture(c);m.playTrainer(A,card(m,A,"trainer").instanceId(),m.activePokemonView(A).pokemonId());if(disabled)m.disableToolEffectsByEffect(A,A,m.activePokemonView(A).pokemonId());boolean free=name.equals("Victini-EX")&&!disabled;check(m.canPayActiveAttackCost(A,attack)==free,"Victory Piece name or disabled state ignored");if(free){m.attack(A,"expensive");check(m.activePokemonView(B).damage()==100,"Victory Piece failed actual unpaid attack");}
    }}
    static void charm(){for(PokemonFamily family:List.of(PokemonFamily.EX,PokemonFamily.EX_LEGACY,PokemonFamily.GX))for(boolean beast:List.of(false,true))for(EnergyType type:List.of(EnergyType.FAIRY,EnergyType.GRASS)){
        var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile("sm9_en_142");c.ownFamilies=beast?Set.of(family,PokemonFamily.ULTRA_BEAST):Set.of(family);c.defenderTypes=Set.of(type);var m=GeneratedRuleBatch28Test.fixture(c);m.attachToolByEffect(A,B,EffectSourceZone.HAND,card(m,B,"trainer").instanceId(),B,m.activePokemonView(B).pokemonId());m.attack(A,"hit");check(m.activePokemonView(B).damage()==(type==EnergyType.FAIRY&&beast&&family!=PokemonFamily.EX?0:100),"Fairy Charm UB lost conjunctive attacker family/type restriction");
    }}
}
